def vowel(c):
    return 1 if c in 'IEAOUY' else 0

def simple(s):
    return sum(vowel(c) for c in s) / len(s)

def prettiness(s):
    n = len(s)
    dp = [defaultdict(int) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(i):
            dp[i][j] = dp[j][j] = simple(s[j:i])
            for k in range(j + 1, i):
                dp[i][j] += dp[k][k]
    return sum(dp[i][j] for i in range(1, n + 1) for j in range(i))

