from collections import deque

def solve():
    player = input()
    N = int(input())
    cubes = []
    for _ in range(N):
        x, y, z = map(int, input().split())
        cubes.append((x, y, z))
    queue = deque([(player, cubes, [])])
    while queue:
        player, cubes, moves = queue.popleft()
        if not cubes:
            return player
        for i, cube in enumerate(cubes):
            for x in range(1, cube[0] + 1):
                for y in range(1, cube[1] + 1):
                    for z in range(1, cube[2] + 1):
                        if (x, y, z) != (cube[0], cube[1], cube[2]):
                            new_cubes = [list(cube) for cube in cubes]
                            new_cubes[i][0] -= x
                            new_cubes[i][1] -= y
                            new_cubes[i][2] -= z
                            new_cubes = [(x, y, z) for x, y, z in new_cubes if x > 0 and y > 0 and z > 0]
                            if new_cubes:
                                queue.append((player, new_cubes, moves + [(x, y, z)]))
    return player

