    count = 0
    for x in range(2, n + 1):
        k = []
        for p in [2, 3, 5]:
            k.append(0)
            while x % p == 0:
                x //= p
                k[-1] += 1
        if x > 1:
            continue
        g = k[0]
        for i in range(1, len(k)):
            g = gcd(g, k[i])
        if g == 1:
            count += 1
    return count

