MOD = 10**9 + 7

@lru_cache(None)
def comb(n, k):
    if k < 0 or k > n:
        return 0
    if k * 2 > n:
        return comb(n, n - k)
    if k == 0:
        return 1
    res = 1
    for i in range(1, k + 1):
        res = res * (n - i + 1) // i % MOD
    return res

@lru_cache(None)
def cost(i, j, k):
    if k == 0:
        return 0
    res = 0
    for x in range(i):
        res += (k - res) * (M - j) % MOD
    for y in range(j):
        res += (k - res) * (N - i) % MOD
    return res

