            temp = [i for i in temp if i != temp[0]]
            temp = [i for i in temp if i != temp[-1]]
            temp = [i if i != temp[-1] else temp[-2] for i in temp]
            temp = [i for i in temp if i != 0]
            temp += [0] * (4 - len(temp))
        grid = list(map(list, zip(*grid)))
    elif direction == 2:  # right
        for row in grid:
            temp = [i for i in reversed(row) if i != 0]
            temp = [i for i in temp if i != temp[0]]
            temp = [i for i in temp if i != temp[-1]]
            temp = [i if i != temp[-1] else temp[-2] for i in temp]
            temp = [i for i in temp if i != 0]
            temp += [0] * (4 - len(temp))
