n, m = map(int, input().split())
field = [list(input()) for _ in range(n)]
directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
visited = [[False] * m for _ in range(n)]

def is_valid(x, y):
    return 0 <= x < n and 0 <= y < m and field[x][y] == '.' and not visited[x][y]

def bfs():
    queue = deque([(0, 0, 0, 0)])
    visited[0][0] = True
    pipes = set()
    while queue:
        x, y, turn, pipe = queue.popleft()
        if x == n - 1 or y == m - 1:
            pipes.add((x, y, turn, pipe))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                queue.append((nx, ny, turn, pipe))
                visited[nx][ny] = True
            elif nx == n - 1 and dy == 0:
                queue.append((nx, ny, turn + 1, pipe + 1))
                visited[nx][ny] = True
            elif ny == m - 1 and dx == 0:
                queue.append((nx, ny, turn + 1, pipe + 1))
                visited[nx][ny] = True
    return len(pipes)

