import random
import math

def simulate_game(R, G, B, Y, S):
    fruits = [R, G, B, Y]
    raven_steps = 0
    while fruits and raven_steps < S:
        die = random.randint(1, 6)
        if die in [1, 2, 3, 4]:
            color = die - 1
            fruits[color] -= 1
        elif die == 5:
            max_fruits = max(fruits)
            max_fruits_index = fruits.index(max_fruits)
            fruits[max_fruits_index] -= 1
        else:
            raven_steps += 1
    return 1 if fruits else 0

def calculate_probability(R, G, B, Y, S):
    wins = 0
    for _ in range(1000000):
        if simulate_game(R, G, B, Y, S):
            wins += 1
    return wins / 1000000

