def on_segment(p, q, r):
    if (q[0] <= max(r[0], p[0]) and q[0] >= min(r[0], p[0]) and
        q[1] <= max(r[1], p[1]) and q[1] >= min(r[1], p[1])):
        return True
    return False

def distance(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def point_line_distance(p, line):
    x0, y0, x1, y1 = line
    return abs((x1 - x0) * (y0 - p[1]) - (x0 - p[0]) * (y1 - y0)) / ((x1 - x0)**2 + (y1 - y0)**2)**0.5

def area_of_polygon(points):
    area = 0
    for i in range(len(points)):
        j = (i + 1) % len(points)
        area += points[i][0] * points[j][1]
        area -= points[j][0] * points[i][1]
    area = abs(area) / 2
    return area

def is_inside(points, x, y):
    n = len(points)
    inside = False
    p1x, p1y = points[0]
    for i in range(n + 1):
        p2x, p2y = points[i % n]
        if y > min(p1y, p2y):
            if y <= max(p1y, p2y):
                if x <= max(p1x, p2x):
                    if p1y != p2y:
                        xinters = (y - p1y) * (p2x - p1x) / (p2y - p1y) + p1x
                    if p1x == p2x or x <= xinters:
                        inside = not inside
        p1x, p1y = p2x, p2y
    return inside

def bfs(points, x, y):
    queue = deque([(x, y, 0)])
    visited = {(x, y)}
    area = 0
    while queue:
        px, py, p_area = queue.popleft()
        area += p_area
        for point in points:
            if on_segment((px, py), point[:2], point[2:]):
                continue
            if point_line_distance((px, py), point[:2:]) < point[2:]:
                continue
            if (px, py) in visited:
                continue
            nx, ny = point[:2]
            queue.append((nx, ny, area + distance((px, py), (nx, ny))))
            visited.add((nx, ny))
    return area

