    def dfs(node, parent):
        nonlocal max_dist
        for neighbor in edges[node]:
            if neighbor == parent:
                continue
            path_gcd = gcd(a[node - 1], a[neighbor - 1])
            if path_gcd > 1:
                dist = 1
                queue = deque([(neighbor, path_gcd, dist)])
                while queue:
