def find_topology(n, edges):
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    def is_bus():
        for node in graph:
            if len(graph[node]) != 2:
                return False
        return True

    def is_ring():
        for node in graph:
            if len(graph[node]) != 2:
                return False
        return True

    def is_star():
        central_node = None
        for node in graph:
            if len(graph[node]) == n - 1:
                if central_node is None:
                    central_node = node
                else:
                    return False
        if central_node is None:
            return False
        for neighbor in graph[central_node]:
            if len(graph[neighbor]) != 1:
                return False
        return True

    if is_bus():
        return "bus topology"
    elif is_ring():
        return "ring topology"
    elif is_star():
        return "star topology"
    else:
        return "unknown topology"

