def sugoroku(N, M, S):
    if S[N] == '1':
        return -1

    dp = [float('inf')] * (N + 1)
    dp[0] = 0
    prev = [None] * (N + 1)

    for i in range(N):
        if S[i] == '1':
            continue
        for x in range(1, M + 1):
            if i + x > N:
                break
            if dp[i] + 1 < dp[i + x]:
                dp[i + x] = dp[i] + 1
                prev[i + x] = i

    if dp[N] == float('inf'):
        return -1

    path = []
    while N > 0:
        path.append(N)
        N = prev[N]

    path.reverse()
    return ' '.join(map(str, path[1:]))

