def count_nice_edges(n, colors, edges):
    tree = defaultdict(list)
    for v, u in edges:
        tree[v].append(u)
        tree[u].append(v)

    red_components = []
    blue_components = []
    visited = [False] * (n + 1)

    def dfs(node, color):
        visited[node] = True
        component = []
        for neighbor in tree[node]:
            if not visited[neighbor]:
                if colors[neighbor - 1] == 0:
                    component.extend(dfs(neighbor, 0))
                elif colors[neighbor - 1] == color:
