            if colors[i - 1] == 1:
                red_components.append(dfs(i, 1))
            elif colors[i - 1] == 2:
                blue_components.append(dfs(i, 2))

    nice_edges = 0
    for red in red_components:
        for blue in blue_components:
            if not any(x in blue for x in red):
                nice_edges += 1

