def find_optimal_restaurant(N, M, hotels, restaurants):
    # Create a graph to store the distances between hotels and restaurants
    graph = defaultdict(list)
    for i, (x1, y1) in enumerate(hotels):
        for j, (x2, y2) in enumerate(restaurants):
            distance = manhattan_distance(x1, y1, x2, y2)
            graph[i].append((j, distance))
            graph[j].append((i, distance))

    # Function to find the maximum distance in the shortest path tree
    def max_distance_in_tree(start):
        distances = [float('inf')] * len(hotels)
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            dist, node = heapq.heappop(pq)
            for neighbor, weight in graph[node]:
                if dist + weight < distances[neighbor]:
                    distances[neighbor] = dist + weight
                    heapq.heappush(pq, (distances[neighbor], neighbor))
        return max(distances)

    # Find the optimal restaurant
    min_max_distance = float('inf')
    optimal_restaurant = -1
    for i in range(len(restaurants)):
        max_dist = max_distance_in_tree(i)
        if max_dist < min_max_distance:
            min_max_distance = max_dist
            optimal_restaurant = i + 1  # +1 because indices are 1-based in the problem

