from typing import List

def min_radius(n: int, lairs: List[List[int]]) -> float:
    lairs.sort()
    left, right = 0, float('inf')
    while right - left > 1e-9:
        mid = (left + right) / 2
        if can_build_reserve(n, lairs, mid):
            right = mid
        else:
            left = mid
    return right if right < float('inf') else -1

def can_build_reserve(n: int, lairs: List[List[int]], radius: float) -> bool:
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = lairs[i]
            x2, y2 = lairs[j]
            d = abs(y1 - y2)
            if d > 2 * radius:
                return False
            if (x1 - x2) ** 2 + (y1 - y2) ** 2 > (2 * radius) ** 2:
                return False
    return True

