from typing import List

def min_trap_cost(n: int, costs: List[int], transitions: List[int]) -> int:
    dp = [float('inf')] * n
    dp[0] = 0

    for _ in range(n):
        new_dp = dp[:]
        for i in range(n):
            if dp[i] != float('inf'):
                new_dp[transitions[i] - 1] = min(new_dp[transitions[i] - 1], dp[i] + costs[i])
        dp = new_dp

    return min(dp)

