import heapq

def min_path_string(n, k, matrix):
    directions = [(0, 1), (1, 0)]
    dp = [[[float('inf')] * 26 for _ in range(n)] for _ in range(n)]
    dp[0][0][ord(matrix[0][0]) - ord('a')] = 0

    pq = [(0, 0, 0, ord(matrix[0][0]) - ord('a'))]

    while pq:
        cost, x, y, char = heapq.heappop(pq)

        if cost > dp[x][y][char]:
            continue

        if x == n-1 and y == n-1:
            return ''.join(chr(ord('a') + c) for c in dp[x][y])

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_char = ord(matrix[nx][ny]) - ord('a')
                new_cost = cost
                if new_char != char:
                    new_cost += 1

                if new_cost < dp[nx][ny][new_char]:
                    dp[nx][ny][new_char] = new_cost
                    heapq.heappush(pq, (new_cost, nx, ny, new_char))

    return ''.join(chr(ord('a') + min(dp[n-1][n-1])) * (2*n-1))

