def find_marks(n, k, p, x, y, marks):
    remaining_tests = n - k
    current_sum = sum(marks)
    current_median = sorted(marks)[(n - 1) // 2]

    if current_sum + remaining_tests * p > x or current_median < y:
        return -1

    target_sum = x - current_sum
    target_median = y

    low, high = 0, p
    while low <= high:
        mid = (low + high) // 2
        if is_possible(mid, remaining_tests, target_sum, target_median):
            if mid == low or not is_possible(mid - 1, remaining_tests, target_sum, target_median):
                return [mid] * remaining_tests
            high = mid - 1
        else:
            low = mid + 1

    return -1

