def find_prime_degree_graph(n):
    if n < 3:
        return -1

    # Calculate the maximum possible number of edges
    max_edges = n * (n - 1) // 2

    # Check if the number of edges can be prime
    for m in range(max_edges, 1, -1):
        if isprime(m):
            # Check if the degrees can be prime
            degrees = [0] * n
            for i in range(m):
                degrees[i % n] += 1
                degrees[(i + 1) % n] += 1
            if all(isprime(d) for d in degrees):
                # Construct the graph
                edges = []
                for i in range(n):
                    for j in range(i + 1, n):
                        if degrees[i] > 1 and degrees[j] > 1:
                            edges.append((i + 1, j + 1))
                            degrees[i] -= 1
                            degrees[j] -= 1
                            m -= 1
                            if m == 0:
                                return m, edges
    return -1

