import sys
from collections import Counter

def sieve(n):
    primes = [0] * (n + 1)
    primes[0] = primes[1] = -1
    for i in range(2, n + 1):
        if primes[i] == 0:
            primes[i] = i
            for j in range(i * i, n + 1, i):
                if primes[j] == 0:
                    primes[j] = i
    return primes

def factorize(x, primes):
    f = Counter()
    while x > 1:
        p = primes[x]
        while x % p == 0:
            x //= p
            f[p] += 1
    return f

def solve(N, V, C):
    primes = sieve(N)
    ingredients = [factorize(i, primes) for i in range(1, N + 1)]
    total_happiness = 0
    for i in range(1, N + 1):
        cost = sum((k ** 2) * C[j] for j, k in ingredients[i - 1].items())
        if cost < V[i - 1]:
            total_happiness += V[i - 1] - cost
    return total_happiness

