    red = False
    blue = False
    for u in adj[v]:
        if u != parent and visited[u] == -1:
            visited[u] = 0
            new_red, new_blue = dfs(u, v, colors, adj, nice_edges, visited)
            red |= new_red
            blue |= new_blue
