                break
        if start_r != -1:
            break

    if start_r == -1:
        return -1

    queue = deque([(start_r, start_c, 0)])
    visited[start_r][start_c] = True

    while queue:
        for _ in range(len(queue)):
            r, c, step = queue.popleft()
            if (r, c) == (0, 0):
                return step

            for dr, dc in directions:
