def find_centers(graph):
    visited = [False] * len(graph)
    centers = []
    for i in range(len(graph)):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            far = i
            farthest = 0
            while stack:
                node = stack.pop()
                if node != far:
                    far = node
                    farthest += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            centers.append((farthest, far))
    return sorted(centers, reverse=True)

def add_edges_to_minimize_diameter(n, centers):
    added_edges = []
    for i in range(0, len(centers), 2):
        if i + 1 < len(centers):
            u, v = centers[i][1], centers[i+1][1]
            added_edges.append((u+1, v+1))
    return added_edges

