def solve(n, queries):
    def find_vertex(u):
        return u if u <= (n + 1) // 2 else n + 1 - u

    def process_path(u, path):
        vertex = find_vertex(u)
        for char in path:
            if char == 'U' and vertex != 1:
                vertex = vertex // 2
            elif char == 'L' and 2 * vertex <= n + 1:
                vertex = 2 * vertex
            elif char == 'R' and 2 * vertex - 1 <= n + 1:
                vertex = 2 * vertex - 1
        return vertex

    answers = []
    for u, path in queries:
        answers.append(process_path(u, path))

    return answers

