from collections import Counter

def can_swap(matrix, row1, col1, row2, col2, K):
    for i in range(len(matrix)):
        if matrix[i][row1] + matrix[row2][i] > K or matrix[i][col1] + matrix[col2][i] > K:
            return False
    return True

def factorial(n, mod):
    result = 1
    for i in range(2, n+1):
        result = (result * i) % mod
    return result

def solve(N, K, matrix, mod=998244353):
    row_counts = Counter(matrix[0])
    col_counts = Counter([matrix[i][0] for i in range(N)])
    res = 1

    for i in range(1, N):
        new_row_counts = Counter(matrix[i])
        for val, count in row_counts.items():
            if val not in col_counts or col_counts[val] < count:
                res = (res * count) % mod
                break
        row_counts = new_row_counts
        col_counts = Counter([matrix[i][j] for j in range(N)])

    for i in range(N):
        for j in range(i+1, N):
            if can_swap(matrix, i, j, j, i, K):
                res = (res * 2) % mod

    for val in row_counts.values():
        res = (res * factorial(val, mod)) % mod
    for val in col_counts.values():
        res = (res * factorial(val, mod)) % mod

    return res

