MOD = 998244353

def inverse(x):
    return pow(x, MOD - 2, MOD)

def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res = (res * i) % MOD
    return res

def solve(p, s, r):
    if r > s or (p == 1 and r != s):
        return 1

    total_ways = factorial(s - r + p - 1)
    hasan_ways = factorial(s - r + p - 1 - (s - r))

    if hasan_ways == 0:
        return 0

    other_players_sum = s - r
    other_players_ways = factorial(other_players_sum + p - 2)
    other_players_ways_each = inverse(other_players_ways)

    total_prob = (hasan_ways * other_players_ways_each) % MOD
    tie_prob = (total_ways - total_prob + MOD) % MOD

    return (tie_prob * inverse(2, MOD)) % MOD

