def max_profit(N, K, prices):
    # Initialize profit list with zeros
    profit = [0] * (K + 1)

    # Iterate over the number of days
    for price in prices:
        # Create a new profit list for the next K days
        new_profit = profit.copy()

        # Update the profit for each number of visits
        for j in range(1, K + 1):
            if j > 1:
                new_profit[j] = max(new_profit[j], new_profit[j - 1] + price)  # Hold
            if j < K:
                new_profit[j] = max(new_profit[j], new_profit[j - 1] - price)  # Sell
            profit[j] = new_profit[j]

    return max(profit)

