    full_glasses = 0

    for _ in range(t):
        for i in range(n):
            if pyramid[i][0] < 1:
                pyramid[i][0] += 1
                full_glasses += 1
            else:
                overflow = pyramid[i][0] - 1
                pyramid[i][0] = 1
                if i > 0:
