from collections import defaultdict

def can_make_acyclic(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = [0] * (n + 1)
    rec_stack = [False] * (n + 1)

    def has_cycle(node):
        if rec_stack[node]:
            return True
        if visited[node]:
            return False

        rec_stack[node] = True
        visited[node] = True

        for neighbor in graph[node]:
            if has_cycle(neighbor):
                return True

        rec_stack[node] = False
        return False

    for node in range(1, n + 1):
        if has_cycle(node):
            # Temporarily remove the edge from node to each of its neighbors
            for neighbor in graph[node]:
                graph[neighbor].remove(node)

            # Check if the graph is acyclic after removing any one edge
            if not any(has_cycle(node) for node in range(1, n + 1)):
                return "YES"

            # Put the edge back
            graph[node].append(neighbor)

    return "NO"

